### Example 1: Group By Pattern

```python
# Group employees by department

employees = [
    {'name': 'Alice',  'dept': 'Eng',       'salary': 95000},
    {'name': 'Bob',    'dept': 'Marketing', 'salary': 72000},
    {'name': 'Carol',  'dept': 'Eng',       'salary': 105000},
    {'name': 'Dave',   'dept': 'HR',        'salary': 68000},
    {'name': 'Eve',    'dept': 'Eng',       'salary': 88000},
    {'name': 'Frank',  'dept': 'Marketing', 'salary': 78000},
]

departments = list(set(e['dept'] for e in employees))

# Nested dict: {dept: {name: salary for employees in dept}}
dept_salaries = {
    dept: {
        emp['name']: emp['salary']
        for emp in employees
        if emp['dept'] == dept
    }
    for dept in departments
}

import json
print(json.dumps(dept_salaries, indent=2))
# {
#   "Eng": {"Alice": 95000, "Carol": 105000, "Eve": 88000},
#   "Marketing": {"Bob": 72000, "Frank": 78000},
#   "HR": {"Dave": 68000}
# }

# Department stats
dept_stats = {
    dept: {
        'count': len(emps),
        'avg_salary': round(sum(emps.values()) / len(emps), 2),
        'max_salary': max(emps.values()),
    }
    for dept, emps in dept_salaries.items()
}
print(dept_stats)
```

### Example 2: Transforming Nested Dicts

```python
# Apply transformation to every value in every nested dict

# Student scores per subject per class
class_scores = {
    'Class_A': {'Math': 85, 'Science': 92, 'English': 78},
    'Class_B': {'Math': 72, 'Science': 68, 'English': 88},
    'Class_C': {'Math': 91, 'Science': 87, 'English': 83},
}

# Add letter grade to each score
def get_grade(score):
    return 'A' if score >= 90 else 'B' if score >= 80 else 'C' if score >= 70 else 'D'

graded = {
    class_name: {
        subject: {'score': score, 'grade': get_grade(score)}
        for subject, score in subjects.items()
    }
    for class_name, subjects in class_scores.items()
}

print(graded['Class_A'])
# {'Math': {'score': 85, 'grade': 'B'},
#  'Science': {'score': 92, 'grade': 'A'},
#  'English': {'score': 78, 'grade': 'C'}}

# Normalize scores per class (divide by class max)
normalized = {
    class_name: {
        subject: round(score / max(subjects.values()), 3)
        for subject, score in subjects.items()
    }
    for class_name, subjects in class_scores.items()
}
print(normalized['Class_A'])
# {'Math': 0.924, 'Science': 1.0, 'English': 0.848}
```

### Example 3: Building a Config Matrix

```python
# Environment × Service matrix of configurations

environments = ['dev', 'staging', 'prod']
services     = ['api', 'worker', 'scheduler']

base_configs = {
    'dev':     {'debug': True,  'replicas': 1,  'log_level': 'DEBUG'},
    'staging': {'debug': False, 'replicas': 2,  'log_level': 'INFO'},
    'prod':    {'debug': False, 'replicas': 4,  'log_level': 'WARNING'},
}

service_overrides = {
    'api':       {'port': 8000, 'timeout': 30},
    'worker':    {'port': None, 'timeout': 300},
    'scheduler': {'port': None, 'timeout': 600},
}

# Build full config matrix
config_matrix = {
    env: {
        service: {**base_configs[env], **service_overrides[service]}
        for service in services
    }
    for env in environments
}

print(config_matrix['prod']['api'])
# {'debug': False, 'replicas': 4, 'log_level': 'WARNING', 'port': 8000, 'timeout': 30}

print(config_matrix['dev']['worker'])
# {'debug': True, 'replicas': 1, 'log_level': 'DEBUG', 'port': None, 'timeout': 300}
```
